160	  /**
161	   * This thread local guards against reentrant calls to {@link #getAdapter(TypeToken)}. In certain
162	   * object graphs, creating an adapter for a type may recursively require an adapter for the same
163	   * type! Without intervention, the recursive lookup would stack overflow. We cheat by returning a
164	   * proxy type adapter, {@link FutureTypeAdapter}, which is wired up once the initial adapter has
165	   * been created.
166	   *
167	   * <p>The map stores the type adapters for ongoing {@code getAdapter} calls, with the type token
168	   * provided to {@code getAdapter} as key and either {@code FutureTypeAdapter} or a regular {@code
169	   * TypeAdapter} as value.
170	   */
171	  @SuppressWarnings("ThreadLocalUsage")
172	  private final ThreadLocal<Map<TypeToken<?>, TypeAdapter<?>>> threadLocalAdapterResults =
173	      new ThreadLocal<>();
174	
175	  private final ConcurrentMap<TypeToken<?>, TypeAdapter<?>> typeTokenCache =
176	      new ConcurrentHashMap<>();
