247	  Gson(GsonBuilder builder) {
248	    this.excluder = builder.excluder;
249	    this.fieldNamingStrategy = builder.fieldNamingPolicy;
250	    this.instanceCreators = new HashMap<>(builder.instanceCreators);
251	    this.serializeNulls = builder.serializeNulls;
252	    this.complexMapKeySerialization = builder.complexMapKeySerialization;
253	    this.generateNonExecutableJson = builder.generateNonExecutableJson;
254	    this.htmlSafe = builder.escapeHtmlChars;
255	    this.formattingStyle = builder.formattingStyle;
256	    this.strictness = builder.strictness;
257	    this.serializeSpecialFloatingPointValues = builder.serializeSpecialFloatingPointValues;
258	    this.useJdkUnsafe = builder.useJdkUnsafe;
259	    this.longSerializationPolicy = builder.longSerializationPolicy;
260	    this.datePattern = builder.datePattern;
261	    this.dateStyle = builder.dateStyle;
262	    this.timeStyle = builder.timeStyle;
263	    this.builderFactories = newImmutableList(builder.factories);
264	    this.builderHierarchyFactories = newImmutableList(builder.hierarchyFactories);
265	    this.objectToNumberStrategy = builder.objectToNumberStrategy;
266	    this.numberToNumberStrategy = builder.numberToNumberStrategy;
267	    this.reflectionFilters = newImmutableList(builder.reflectionFilters);
268	    if (builder == GsonBuilder.DEFAULT) {
269	      this.constructorConstructor = GsonBuilder.DEFAULT_CONSTRUCTOR_CONSTRUCTOR;
270	      this.jsonAdapterFactory = GsonBuilder.DEFAULT_JSON_ADAPTER_ANNOTATION_TYPE_ADAPTER_FACTORY;
271	      this.factories = GsonBuilder.DEFAULT_TYPE_ADAPTER_FACTORIES;
272	    } else {
273	      this.constructorConstructor =
274	          new ConstructorConstructor(instanceCreators, useJdkUnsafe, reflectionFilters);
275	      this.jsonAdapterFactory = new JsonAdapterAnnotationTypeAdapterFactory(constructorConstructor);
276	      this.factories = builder.createFactories(constructorConstructor, jsonAdapterFactory);
277	    }
278	  }
