329	  /**
330	   * Returns the type adapter for {@code type}.
331	   *
332	   * <p>When calling this method concurrently from multiple threads and requesting an adapter for
333	   * the same type this method may return different {@code TypeAdapter} instances. However, that
334	   * should normally not be an issue because {@code TypeAdapter} implementations are supposed to be
335	   * stateless.
336	   *
337	   * @throws IllegalArgumentException if this Gson instance cannot serialize and deserialize {@code
338	   *     type}.
339	   */
340	  public <T> TypeAdapter<T> getAdapter(TypeToken<T> type) {
341	    Objects.requireNonNull(type, "type must not be null");
342	    TypeAdapter<?> cached = typeTokenCache.get(type);
343	    if (cached != null) {
344	      @SuppressWarnings("unchecked")
345	      TypeAdapter<T> adapter = (TypeAdapter<T>) cached;
346	      return adapter;
347	    }
348	
349	    Map<TypeToken<?>, TypeAdapter<?>> threadCalls = threadLocalAdapterResults.get();
350	    boolean isInitialAdapterRequest = false;
351	    if (threadCalls == null) {
352	      threadCalls = new HashMap<>();
353	      threadLocalAdapterResults.set(threadCalls);
354	      isInitialAdapterRequest = true;
355	    } else {
356	      // the key and value type parameters always agree
357	      @SuppressWarnings("unchecked")
358	      TypeAdapter<T> ongoingCall = (TypeAdapter<T>) threadCalls.get(type);
359	      if (ongoingCall != null) {
360	        return ongoingCall;
361	      }
362	    }
363	
364	    TypeAdapter<T> candidate = null;
365	    try {
366	      FutureTypeAdapter<T> call = new FutureTypeAdapter<>();
367	      threadCalls.put(type, call);
368	
369	      for (TypeAdapterFactory factory : factories) {
370	        candidate = factory.create(this, type);
371	        if (candidate != null) {
372	          call.setDelegate(candidate);
373	          // Replace future adapter with actual adapter
374	          threadCalls.put(type, candidate);
375	          break;
376	        }
377	      }
378	    } finally {
379	      if (isInitialAdapterRequest) {
380	        threadLocalAdapterResults.remove();
381	      }
382	    }
383	
384	    if (candidate == null) {
385	      throw new IllegalArgumentException(
386	          "GSON (" + GsonBuildConfig.VERSION + ") cannot handle " + type);
387	    }
388	
389	    if (isInitialAdapterRequest) {
390	      /*
391	       * Publish resolved adapters to all threads
392	       * Can only do this for the initial request because cyclic dependency TypeA -> TypeB -> TypeA
393	       * would otherwise publish adapter for TypeB which uses not yet resolved adapter for TypeA
394	       * See https://github.com/google/gson/issues/625
395	       */
396	      typeTokenCache.putAll(threadCalls);
397	    }
398	    return candidate;
399	  }
