401	  /**
402	   * Returns the type adapter for {@code type}.
403	   *
404	   * @throws IllegalArgumentException if this Gson instance cannot serialize and deserialize {@code
405	   *     type}.
406	   */
407	  public <T> TypeAdapter<T> getAdapter(Class<T> type) {
408	    return getAdapter(TypeToken.get(type));
409	  }
