998	   * @see #fromJson(Reader, Class)
999	   * @since 2.10
1000	   */
1001	  public <T> T fromJson(Reader json, TypeToken<T> typeOfT)
1002	      throws JsonIOException, JsonSyntaxException {
1003	    JsonReader jsonReader = newJsonReader(json);
1004	    T object = fromJson(jsonReader, typeOfT);
1005	    assertFullConsumption(object, jsonReader);
1006	    return object;
1007	  }
1008	
1009	  // fromJson(JsonReader, Class) is unfortunately missing and cannot be added now without breaking
1010	  // source compatibility in certain cases, see
1011	  // https://github.com/google/gson/pull/1700#discussion_r973764414
1012	
1013	  /**
1014	   * Reads the next JSON value from {@code reader} and converts it to an object of type {@code
1015	   * typeOfT}. Returns {@code null}, if the {@code reader} is at EOF.
1016	   *
1017	   * <p>Since {@code Type} is not parameterized by T, this method is not type-safe and should be
1018	   * used carefully. If you are creating the {@code Type} from a {@link TypeToken}, prefer using
1019	   * {@link #fromJson(JsonReader, TypeToken)} instead since its return type is based on the {@code
1020	   * TypeToken} and is therefore more type-safe. If the provided type is a {@code Class} the {@code
1021	   * TypeToken} can be created with {@link TypeToken#get(Class)}.
1022	   *
1023	   * <p>Unlike the other {@code fromJson} methods, no exception is thrown if the JSON data has
1024	   * multiple top-level JSON elements, or if there is trailing data.
1025	   *
1026	   * <p>If the {@code Gson} instance has an {@linkplain GsonBuilder#setStrictness(Strictness)
1027	   * explicit strictness setting}, this setting will be used for reading the JSON regardless of the
1028	   * {@linkplain JsonReader#getStrictness() strictness} of the provided {@link JsonReader}. For
1029	   * legacy reasons, if the {@code Gson} instance has no explicit strictness setting and the reader
1030	   * does not have the strictness {@link Strictness#STRICT}, the JSON will be written in {@link
1031	   * Strictness#LENIENT} mode.<br>
1032	   * Note that in all cases the old strictness setting of the reader will be restored when this
1033	   * method returns.
1034	   *
1035	   * @param <T> the type of the desired object
1036	   * @param reader the reader whose next JSON value should be deserialized
1037	   * @param typeOfT The specific genericized type of src
1038	   * @return an object of type T from the JsonReader. Returns {@code null} if {@code reader} is at
1039	   *     EOF.
1040	   * @throws JsonIOException if there was a problem reading from the JsonReader
1041	   * @throws JsonSyntaxException if json is not a valid representation for an object of type typeOfT
1042	   * @see #fromJson(Reader, Type)
1043	   * @see #fromJson(JsonReader, TypeToken)
1044	   */
1045	  @SuppressWarnings({"unchecked", "TypeParameterUnusedInFormals"})
