1051	  /**
1052	   * Reads the next JSON value from {@code reader} and converts it to an object of type {@code
1053	   * typeOfT}. Returns {@code null}, if the {@code reader} is at EOF. This method is useful if the
1054	   * specified object is a generic type. For non-generic objects, {@link #fromJson(JsonReader,
1055	   * Type)} can be called, or {@link TypeToken#get(Class)} can be used to create the type token.
1056	   *
1057	   * <p>Unlike the other {@code fromJson} methods, no exception is thrown if the JSON data has
1058	   * multiple top-level JSON elements, or if there is trailing data.
1059	   *
1060	   * <p>If the {@code Gson} instance has an {@linkplain GsonBuilder#setStrictness(Strictness)
1061	   * explicit strictness setting}, this setting will be used for reading the JSON regardless of the
1062	   * {@linkplain JsonReader#getStrictness() strictness} of the provided {@link JsonReader}. For
1063	   * legacy reasons, if the {@code Gson} instance has no explicit strictness setting and the reader
1064	   * does not have the strictness {@link Strictness#STRICT}, the JSON will be written in {@link
1065	   * Strictness#LENIENT} mode.<br>
1066	   * Note that in all cases the old strictness setting of the reader will be restored when this
1067	   * method returns.
1068	   *
1069	   * @param <T> the type of the desired object
1070	   * @param reader the reader whose next JSON value should be deserialized
1071	   * @param typeOfT The specific genericized type of src. You should create an anonymous subclass of
1072	   *     {@code TypeToken} with the specific generic type arguments. For example, to get the type
1073	   *     for {@code Collection<Foo>}, you should use:
1074	   *     <pre>
1075	   * new TypeToken&lt;Collection&lt;Foo&gt;&gt;(){}
1076	   * </pre>
1077	   *
1078	   * @return an object of type T from the JsonReader. Returns {@code null} if {@code reader} is at
1079	   *     EOF.
1080	   * @throws JsonIOException if there was a problem reading from the JsonReader
1081	   * @throws JsonSyntaxException if json is not a valid representation for an object of the type
1082	   *     typeOfT
1083	   * @see #fromJson(Reader, TypeToken)
1084	   * @see #fromJson(JsonReader, Type)
1085	   * @since 2.10
1086	   */
1087	  public <T> T fromJson(JsonReader reader, TypeToken<T> typeOfT)
1088	      throws JsonIOException, JsonSyntaxException {
1089	    boolean isEmpty = true;
1090	    Strictness oldStrictness = reader.getStrictness();
1091	
1092	    if (this.strictness != null) {
1093	      reader.setStrictness(this.strictness);
1094	    } else if (reader.getStrictness() == Strictness.LEGACY_STRICT) {
1095	      // For backward compatibility change to LENIENT if reader has default strictness LEGACY_STRICT
1096	      reader.setStrictness(Strictness.LENIENT);
1097	    }
1098	
1099	    try {
1100	      JsonToken unused = reader.peek();
1101	      isEmpty = false;
1102	      TypeAdapter<T> typeAdapter = getAdapter(typeOfT);
1103	      T object = typeAdapter.read(reader);
1104	      Class<?> expectedTypeWrapped = Primitives.wrap(typeOfT.getRawType());
1105	      if (object != null && !expectedTypeWrapped.isInstance(object)) {
1106	        throw new ClassCastException(
1107	            "Type adapter '"
1108	                + typeAdapter
1109	                + "' returned wrong type; requested "
1110	                + typeOfT.getRawType()
1111	                + " but got instance of "
1112	                + object.getClass()
1113	                + "\nVerify that the adapter was registered for the correct type.");
1114	      }
1115	      return object;
1116	    } catch (EOFException e) {
1117	      /*
1118	       * For compatibility with JSON 1.5 and earlier, we return null for empty
1119	       * documents instead of throwing.
1120	       */
1121	      if (isEmpty) {
1122	        return null;
1123	      }
1124	      throw new JsonSyntaxException(e);
1125	    } catch (IllegalStateException e) {
1126	      throw new JsonSyntaxException(e);
1127	    } catch (IOException e) {
1128	      // TODO(inder): Figure out whether it is indeed right to rethrow this as JsonSyntaxException
1129	      throw new JsonSyntaxException(e);
1130	    } catch (AssertionError e) {
1131	      throw new AssertionError(
1132	          "AssertionError (GSON " + GsonBuildConfig.VERSION + "): " + e.getMessage(), e);
1133	    } finally {
1134	      reader.setStrictness(oldStrictness);
1135	    }
