1218	
1219	  private static void assertFullConsumption(Object obj, JsonReader reader) {
1220	    try {
1221	      if (obj != null && reader.peek() != JsonToken.END_DOCUMENT) {
1222	        throw new JsonSyntaxException("JSON document was not fully consumed.");
1223	      }
1224	    } catch (MalformedJsonException e) {
1225	      throw new JsonSyntaxException(e);
1226	    } catch (IOException e) {
1227	      throw new JsonIOException(e);
1228	    }
1229	  }
1230	
1231	  /**
1232	   * Proxy type adapter for cyclic type graphs.
1233	   *
1234	   * <p><b>Important:</b> Setting the delegate adapter is not thread-safe; instances of {@code
1235	   * FutureTypeAdapter} must only be published to other threads after the delegate has been set.
1236	   *
1237	   * @see Gson#threadLocalAdapterResults
1238	   */
1239	  static class FutureTypeAdapter<T> extends SerializationDelegatingTypeAdapter<T> {
1240	    private TypeAdapter<T> delegate = null;
1241	
1242	    public void setDelegate(TypeAdapter<T> typeAdapter) {
1243	      if (delegate != null) {
1244	        throw new AssertionError("Delegate is already set");
1245	      }
1246	      delegate = typeAdapter;
1247	    }
1248	
1249	    private TypeAdapter<T> delegate() {
1250	      TypeAdapter<T> delegate = this.delegate;
1251	      if (delegate == null) {
1252	        // Can occur when adapter is leaked to other thread or when adapter is used for
1253	        // (de-)serialization
1254	        // directly within the TypeAdapterFactory which requested it
1255	        throw new IllegalStateException(
1256	            "Adapter for type with cyclic dependency has been used"
1257	                + " before dependency has been resolved");
1258	      }
1259	      return delegate;
1260	    }
1261	
1262	    @Override
1263	    public TypeAdapter<T> getSerializationDelegate() {
1264	      return delegate();
1265	    }
1266	
1267	    @Override
1268	    public T read(JsonReader in) throws IOException {
1269	      return delegate().read(in);
1270	    }
1271	
1272	    @Override
1273	    public void write(JsonWriter out, T value) throws IOException {
1274	      delegate().write(out, value);
1275	    }
1276	  }
